use super::*;
use quantum_ecc::sim::Simulator;
struct Fixed(u8);impl sha3::digest::XofReader for Fixed{fn read(&mut self,out:&mut[u8]){out.fill(self.0);}}
fn algebra()->Algebra{Algebra{next:1,cap:256,degree:12,cuts:0}}
fn gate(k:K,a:u64,b:u64,t:u64)->Op{let mut o=Op::empty();o.kind=k;o.q_control1=QubitId(a);o.q_control2=QubitId(b);o.q_target=QubitId(t);o}
fn fixture()->Vec<Op>{(0..3).map(|t|{let mut o=gate(K::AppendToRegister,NO,NO,t);o.r_target.0=0;o}).collect()}
fn classical_input(v:&mut Vec<Op>){let mut o=Op::empty();o.kind=K::AppendToRegister;o.c_target.0=0;o.r_target.0=1;v.push(o);}
fn pair(v:&[Op],out:&[Op]){for pattern in [0,255,0xa5,0x5a]{for input in 0..16{let mut ra=Fixed(pattern);let mut rb=Fixed(pattern);let mut a=Simulator::new(8,2,&mut ra);let mut b=Simulator::new(8,2,&mut rb);a.phase=0xa55a;a.qubits[0]=input&1;a.qubits[1]=input>>1&1;a.qubits[2]=input>>2&1;a.bits[0]=input>>3&1;b.qubits.clone_from(&a.qubits);b.bits.clone_from(&a.bits);b.phase=a.phase;a.apply_iter(v.iter());b.apply_iter(out.iter());assert_eq!(a.qubits,b.qubits);assert_eq!(a.bits,b.bits);assert_eq!(a.phase,b.phase);}}}
fn optimized(v:&[Op])->(Vec<Op>,Vec<serde_json::Value>){scan_with_witness(v,&mut algebra(),true)}
fn witness_count(s:&[serde_json::Value])->usize{s.iter().filter(|x|x["kind"]=="exact_current_wire_product").count()}
#[test]fn exact_and_complemented_current_wire_products_preserve_every_basis_input(){let mut v=fixture();v.extend([gate(K::CCX,0,1,3),gate(K::CCX,0,1,4),gate(K::CX,3,NO,4),gate(K::X,NO,NO,3),gate(K::CCX,0,1,5)]);let(out,s)=optimized(&v);assert_eq!(witness_count(&s),2);assert_eq!(s.last().unwrap()["complement"],true);assert_eq!(out.iter().filter(|x|x.kind==K::CCX).count(),1);pair(&v,&out);let(disabled,_)=scan_with_witness(&v,&mut algebra(),false);assert_eq!(disabled,v);}
#[test]fn target_is_never_its_own_product_witness(){let mut v=fixture();v.extend([gate(K::CCX,0,1,3),gate(K::CCX,0,1,3)]);let(out,s)=optimized(&v);assert_eq!(witness_count(&s),0);assert_eq!(out,v);pair(&v,&out);}
#[test]fn arbitrary_mutation_invalidates_a_stale_witness(){let mut v=fixture();v.extend([gate(K::CCX,0,1,3),gate(K::CX,2,NO,3),gate(K::CCX,0,1,4)]);let(out,s)=optimized(&v);assert_eq!(witness_count(&s),0);pair(&v,&out);}
#[test]fn swap_reindexes_both_physical_wires(){let mut v=fixture();v.extend([gate(K::CCX,0,1,3),gate(K::Swap,3,NO,4),gate(K::CCX,0,1,5)]);let(out,s)=optimized(&v);assert_eq!(witness_count(&s),1);assert_eq!(s.last().unwrap()["witness"],4);pair(&v,&out);}
#[test]fn condition_snapshots_and_guarded_writes_preserve_index_values(){let mut v=fixture();classical_input(&mut v);v.push(gate(K::CCX,0,1,3));let mut push=Op::empty();push.kind=K::PushCondition;push.c_condition.0=0;let mut invert=Op::empty();invert.kind=K::BitInvert;invert.c_target.0=0;let mut pop=Op::empty();pop.kind=K::PopCondition;v.extend([push,invert,gate(K::CCX,0,1,4),gate(K::X,NO,NO,3),pop,gate(K::CCX,0,1,5)]);let(out,s)=optimized(&v);assert!(witness_count(&s)>=1);pair(&v,&out);}
#[test]fn measurement_and_reset_remove_the_old_product_witness(){for kind in [K::Hmr,K::R]{let mut v=fixture();classical_input(&mut v);let mut reset=gate(kind,NO,NO,3);if kind==K::Hmr{reset.c_target.0=0;}v.extend([gate(K::CCX,0,1,3),reset,gate(K::CCX,0,1,4)]);let(out,s)=optimized(&v);assert_eq!(witness_count(&s),0);pair(&v,&out);}}
#[test]fn oversized_complement_query_does_not_mutate_the_algebra(){let mut index=Witnesses::default();let p:P=(1..=256).map(|x|vec![x]).collect();index.insert(7,&p);assert_eq!(index.find(&p,0,1,2,256),Some((7,false)));let mut shifted=p.clone();shifted.push(vec![257]);assert_eq!(index.find(&shifted,0,1,2,256),None);index.remove(7,&p);assert!(index.0.is_empty());}
